function extractTagContent(xmlSnippet, tagName) {
  // Escapar posibles caracteres especiales en el tagName como ":"
  const escapedTag = tagName.replace(/([.*+?^=!:${}()|\[\]\/\\])/g, '\\$1');
  const regex = new RegExp('<' + escapedTag + '(?:\\s+[^>]*)?>([\\s\\S]*?)<\\/' + escapedTag + '>', 'i');
